import java.util.*;

class Solution {
  public int[][] reconstructQueue(int[][] people) {
    // tallest first; inserting at index k keeps exactly k taller-or-equal people in front
    Arrays.sort(people, (a, b) -> a[0] != b[0] ? Integer.compare(b[0], a[0]) : Integer.compare(a[1], b[1]));
    List<int[]> queue = new ArrayList<>();
    for (int[] p : people) queue.add(p[1], p);
    return queue.toArray(new int[0][]);
  }
}
